425	// trailWebURL builds a fallback browser URL for a trail used only when the
426	// server does not supply one (older servers):
427	// <web-origin>/<forge>/<owner>/<repo>/trails/<number>. In production the web app
428	// is served from the same origin as the data API, so the API base URL doubles
429	// as the web origin. A split local-dev setup (API and frontend on different
430	// ports) would point this at the API port rather than the dev frontend.
431	func trailWebURL(base, forge, owner, repo string, number int) string {
432		return strings.TrimRight(base, "/") + "/" + forge + "/" + owner + "/" + repo + "/trails/" + strconv.Itoa(number)
433	}
434	
435	// fetchTrailDescriptionAtPath fetches a trail's rendered description text
436	// (`trail.body_document.text_snapshot`) and its etag, which the list endpoint
437	// omits, by integer number. It returns only the description and etag — the
438	// list result already supplies the metadata — and decodes only the fields it
439	// needs, so it is unaffected by the shape of sibling fields like
440	// `checkpoints`/`thread`.
441	func fetchTrailDescriptionAtPath(ctx context.Context, client *api.Client, basePath string, number int) (string, string, error) {
442		resp, err := client.Get(ctx, trailNumberPathForBase(basePath, number))
443		if err != nil {
444			return "", "", fmt.Errorf("failed to fetch trail detail: %w", err)
445		}
446		defer resp.Body.Close()
447		if err := checkTrailResponse(resp); err != nil {
448			return "", "", err
449		}
450		detail, err := decodeTrailResource(resp)
451		if err != nil {
452			return "", "", fmt.Errorf("failed to decode trail detail: %w", err)
453		}
454		if detail.BodyDocument == nil {
455			return "", "", nil
456		}
457		return strings.TrimSpace(detail.BodyDocument.TextSnapshot), detail.BodyDocument.ETag, nil
458	}
